#include <stdio.h>
#include <stdlib.h>
#include <sys/utsname.h>
#include <errno.h>
#include <string.h>

int main() {
    struct utsname u_info;

    // Attempt to retrieve system information
    if (uname(&u_info) == -1) {
        fprintf(stderr, "Error calling uname(): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Print retrieved system information fields
    printf("System Information:\n");
    printf("  OS Name (sysname):    %s\n", u_info.sysname);
    printf("  Node Name (nodename): %s\n", u_info.nodename);
    printf("  Release:              %s\n", u_info.release);
    printf("  Version:              %s\n", u_info.version);
    printf("  Machine (arch):       %s\n", u_info.machine);

    return EXIT_SUCCESS;
}
